// src/Pages/AdminDashboard.js
import React, { useEffect, useState } from "react";
import { auth } from "../firebase";
import { useNavigate } from "react-router-dom";
import NavBar from "../Components/NavBar";
import "./adminDashboard.css";

export default function AdminDashboard() {
  const [users, setUsers] = useState([]);
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);
  const [editingUser, setEditingUser] = useState(null);

  // Editable fields
  const [editEmail, setEditEmail] = useState("");
  const [editUsername, setEditUsername] = useState("");
  const [editWhatsapp, setEditWhatsapp] = useState(""); // ✅ WhatsApp field
  const [editDate, setEditDate] = useState("");

  const navigate = useNavigate();
  const API_BASE_URL = "http://localhost:5000";

  // Restrict dashboard access
  useEffect(() => {
    const user = auth.currentUser;
    if (!user || user.email !== "yasasmigunasinghe@gmail.com") {
      navigate("/account");
    }
  }, [navigate]);

  // Fetch all users
  const fetchUsers = async () => {
    setLoading(true);
    setError("");
    try {
      const res = await fetch(`${API_BASE_URL}/users`);
      if (!res.ok) {
        const text = await res.text();
        throw new Error(`Failed to fetch users: ${res.status} ${text}`);
      }
      const data = await res.json();
      setUsers(data);
    } catch (err) {
      setError(err.message);
    }
    setLoading(false);
  };

  useEffect(() => {
    fetchUsers();
  }, []);

  // Delete user
  const handleDelete = async (uid) => {
    setError("");
    try {
      const res = await fetch(`${API_BASE_URL}/users/${uid}`, {
        method: "DELETE",
      });
      if (!res.ok) {
        const text = await res.text();
        throw new Error(`Failed to delete user: ${res.status} ${text}`);
      }
      fetchUsers();
    } catch (err) {
      setError(err.message);
    }
  };

  // Start editing a row
  const startEdit = (user) => {
    setEditingUser(user);
    setEditEmail(user.email);
    setEditUsername(user.username || "");
    setEditWhatsapp(user.whatsapp || ""); // ✅ WhatsApp value
    setEditDate(user.createdAt || "");
  };

  const cancelEdit = () => {
    setEditingUser(null);
    setError("");
  };

  // Submit edit
  const submitEdit = async () => {
    try {
      const res = await fetch(`${API_BASE_URL}/users/${editingUser.uid}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          email: editEmail,
          username: editUsername,
          whatsapp: editWhatsapp, // ✅ send WhatsApp to backend
        }),
      });
      if (!res.ok) {
        const text = await res.text();
        throw new Error(`Failed to update user: ${res.status} ${text}`);
      }
      setEditingUser(null);
      fetchUsers();
    } catch (err) {
      setError(err.message);
    }
  };

  return (
    <div className="admin-container">
      <NavBar />
      <h2>Admin User Management</h2>
      {error && <p className="error-message">{error}</p>}
      {loading ? (
        <p>Loading users...</p>
      ) : (
        <table className="admin-table">
          <thead>
            <tr>
              <th>Username</th>
              <th>Email</th>
              <th>WhatsApp</th> {/* ✅ Added WhatsApp column */}
              <th>Date Registered</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {users.length === 0 ? (
              <tr>
                <td colSpan="5" style={{ textAlign: "center" }}>
                  No users found
                </td>
              </tr>
            ) : (
              users.map((user) =>
                editingUser && editingUser.uid === user.uid ? (
                  <tr key={user.uid}>
                    <td>
                      <input
                        value={editUsername}
                        onChange={(e) => setEditUsername(e.target.value)}
                      />
                    </td>
                    <td>
                      <input
                        value={editEmail}
                        onChange={(e) => setEditEmail(e.target.value)}
                      />
                    </td>
                    <td>
                      <input
                        value={editWhatsapp}
                        onChange={(e) => setEditWhatsapp(e.target.value)}
                      />
                    </td>
                    <td>
                      <input value={editDate} disabled />
                    </td>
                    <td>
                      <button className="btn-save" onClick={submitEdit}>
                        Save
                      </button>
                      <button className="btn-cancel" onClick={cancelEdit}>
                        Cancel
                      </button>
                    </td>
                  </tr>
                ) : (
                  <tr key={user.uid}>
                    <td>{user.username || "-"}</td>
                    <td>{user.email}</td>
                    <td>{user.whatsapp || "-"}</td> {/* ✅ Display WhatsApp */}
                    <td>
                      {user.createdAt
                        ? new Date(user.createdAt).toLocaleDateString()
                        : "-"}
                    </td>
                    <td>
                      <button
                        className="btn-edit"
                        onClick={() => startEdit(user)}
                      >
                        Edit
                      </button>
                      <button
                        className="btn-delete"
                        onClick={() => handleDelete(user.uid)}
                      >
                        Delete
                      </button>
                    </td>
                  </tr>
                )
              )
            )}
          </tbody>
        </table>
      )}
    </div>
  );
}
